import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Medicament } from 'src/app/models/Medicament';
import { FournisseurService } from 'src/app/services/fournisseur.service';
import { CommandeService } from 'src/app/services/commande.service';

@Component({
  selector: 'app-medicament-list',
  templateUrl: './medicament-list.component.html',
  styleUrls: ['./medicament-list.component.css']
})
export class MedicamentListComponent implements OnInit {
  medicaments: Medicament[] = [];  // Liste des médicaments
  fournisseurId: number = 0;
  selectedMedicaments: { medicamentId: number, quantite: number }[] = [];  // Médicaments sélectionnés pour la commande
  selectedMedicament: Medicament | null = null;  // Médicament actuellement sélectionné pour la commande
  quantite: number = 1;  // Quantité à commander

  constructor(
    private fournisseurService: FournisseurService,
    private route: ActivatedRoute,
    private commandeService: CommandeService
  ) {}

  ngOnInit(): void {
    // Récupérer l'ID du fournisseur depuis les paramètres de la route
    this.fournisseurId = Number(this.route.snapshot.paramMap.get('id'));  // Convertir l'ID en nombre
    if (this.fournisseurId) {
      this.getMedicamentsByFournisseur(this.fournisseurId);
    }
  }

  // Récupérer les médicaments d'un fournisseur
  getMedicamentsByFournisseur(idFournisseur: number): void {
    this.fournisseurService.getMedicamentsByFournisseur(idFournisseur).subscribe(
      data => {
        this.medicaments = data || [];  // S'assurer que la liste n'est jamais vide
      },
      error => {
        console.error('Erreur lors de la récupération des médicaments', error);
        this.medicaments = [];
      }
    );
  }

  // Ouvrir la fenêtre de quantité pour un médicament spécifique
  openQuantityDialog(medicament: Medicament): void {
    this.selectedMedicament = medicament;
    this.quantite = 1;  // Réinitialiser la quantité
  }

  // Mettre à jour la sélection de médicaments avec la quantité
  updateSelection(medicamentId: number, quantite: number): void {
    if (quantite < 1) return;  // Empêcher une quantité invalide

    const existing = this.selectedMedicaments.find(item => item.medicamentId === medicamentId);
    if (existing) {
      existing.quantite = quantite;
    } else {
      this.selectedMedicaments.push({ medicamentId, quantite });
    }
  }

  // Ajouter le médicament à la commande
  addToSelection(medicament: Medicament): void {
    if (this.quantite < 1) return;  // Valider la quantité avant d'ajouter
    this.selectedMedicaments.push({ medicamentId: medicament.idmedicament, quantite: this.quantite });
    this.selectedMedicament = null;  // Fermer la fenêtre de saisie de quantité
  }

  // Passer la commande
  passerCommande(): void {
    if (this.selectedMedicaments.length === 0) return;  // Empêcher de passer une commande vide

    const commande = {
      fournisseurId: this.fournisseurId,
      status: 'Encours',
      medicaments: this.selectedMedicaments
    };

    this.commandeService.passerCommande(commande).subscribe(
      response => {
        console.log('Commande passée avec succès', response);
        alert('Commande passée avec succès !');
        this.selectedMedicaments = [];  // Réinitialiser la sélection
      },
      error => {
        console.error('Erreur lors de la commande', error);
        alert('Erreur lors de la commande.');
      }
    );
  }
}
<h2>Liste des Médicaments</h2>

<!-- Liste des médicaments -->
<ul *ngIf="medicaments && medicaments.length > 0; else noMedicament">
  <li *ngFor="let medicament of medicaments">
    {{ medicament.nom }} - Prix: {{ medicament.prix }}€

    <!-- Bouton pour afficher le champ de quantité -->
    <button (click)="openQuantityDialog(medicament)">
      Commander
    </button>

    <!-- Affichage de la fenêtre de saisie de la quantité si la commande est en cours -->
    <div *ngIf="medicament === selectedMedicament">
      <input 
        type="number" 
        [(ngModel)]="quantite" 
        min="1" 
        placeholder="Quantité"
        (change)="updateSelection(medicament.idmedicament, quantite)">
      <button (click)="addToSelection(medicament)">Ajouter à la commande</button>
    </div>
  </li>
</ul>

<!-- Message lorsqu'il n'y a pas de médicaments -->
<ng-template #noMedicament>
  <p>Aucun médicament disponible pour ce fournisseur.</p>
</ng-template>

<!-- Bouton pour passer la commande -->
<button (click)="passerCommande()" [disabled]="selectedMedicaments.length === 0">
  Passer la Commande
</button>
